import React, { useEffect, useState } from "react";
import Layout from "../components/Layout";
import api from "../services/api";

const Patients = () => {
    const [patients, setPatients] = useState([]);
    const [search, setSearch] = useState("");
    const [loading, setLoading] = useState(true);

    // ✅ Popup States
    const [showModal, setShowModal] = useState(false);
    const [selectedPatient, setSelectedPatient] = useState(null);
    const [billingHistory, setBillingHistory] = useState([]);

    // ✅ Fetch Patients List
    const fetchPatients = async () => {
        try {
            const res = await api.get("/patients");
            setPatients(res.data);
            setLoading(false);
        } catch (error) {
            console.log("Error fetching patients:", error);
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchPatients();
    }, []);

    // ✅ Search Filter
    const filteredPatients = patients.filter((p) => {
        const nameMatch = p.name
            ?.toLowerCase()
            .includes(search.toLowerCase());

        const phoneMatch = String(p.phone || "").includes(search);

        return nameMatch || phoneMatch;
    });

    // =====================================================
    // ✅ Open Popup + Fetch Billing History
    // =====================================================
    const openBillingPopup = async (patient) => {
        setSelectedPatient(patient);
        setShowModal(true);

        try {
            const res = await api.get(`/bill/${patient.phone}`);
            setBillingHistory(res.data);
        } catch (error) {
            console.log("Error fetching billing history:", error);
        }
    };

    // ✅ Close Popup
    const closePopup = () => {
        setShowModal(false);
        setSelectedPatient(null);
        setBillingHistory([]);
    };

    return (
        <Layout>
            <div className="container-fluid">

                {/* Page Header */}
                <h2 className="fw-bold text-primary mb-4">
                    👨‍⚕️ Patients Management
                </h2>

                {/* Search Bar */}
                <input
                    type="text"
                    className="form-control mb-3"
                    placeholder="🔍 Search by Name or Phone..."
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                />

                {/* Loading */}
                {loading ? (
                    <h5 className="text-center text-muted">Loading Patients...</h5>
                ) : (
                    <div className="card shadow-lg border-0">

                        <div className="card-header bg-dark text-white fw-bold">
                            📋 Patients List
                        </div>

                        <div className="card-body table-responsive">
                            <table className="table table-bordered table-hover text-center">
                                <thead className="table-secondary">
                                    <tr>
                                        <th>#</th>
                                        <th>Patient Name</th>
                                        <th>Age</th>
                                        <th>Phone</th>
                                        <th>Billing History</th>
                                    </tr>
                                </thead>

                                <tbody>
                                    {filteredPatients.length > 0 ? (
                                        filteredPatients.map((p, index) => (
                                            <tr key={p._id || index}>
                                                <td>{index + 1}</td>
                                                <td className="fw-semibold">{p.name}</td>
                                                <td>{p.age}</td>
                                                <td>{p.phone}</td>

                                                {/* ✅ Popup Button */}
                                                <td>
                                                    <button
                                                        className="btn btn-sm btn-primary"
                                                        onClick={() => openBillingPopup(p)}
                                                    >
                                                        🧾 View Bills
                                                    </button>
                                                </td>
                                            </tr>
                                        ))
                                    ) : (
                                        <tr>
                                            <td colSpan="5">No patients found</td>
                                        </tr>
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>
                )}

                {/* =====================================================
            ✅ BILLING POPUP MODAL
        ===================================================== */}
                {showModal && (
                    <div
                        className="modal fade show"
                        style={{ display: "block", backgroundColor: "rgba(0,0,0,0.5)" }}
                    >
                        <div className="modal-dialog modal-lg">
                            <div className="modal-content">

                                {/* Modal Header */}
                                <div className="modal-header bg-primary text-white">
                                    <h5 className="modal-title">
                                        🧾 Billing History - {selectedPatient?.name}
                                    </h5>
                                    <button
                                        className="btn-close btn-close-white"
                                        onClick={closePopup}
                                    ></button>
                                </div>

                                {/* Modal Body */}
                                <div className="modal-body">
                                    {billingHistory.length > 0 ? (
                                        <table className="table table-bordered text-center">
                                            <thead className="table-dark">
                                                <tr>
                                                    <th>Date</th>
                                                    <th>Service</th>
                                                    <th>Amount</th>
                                                    <th>Status</th>
                                                </tr>
                                            </thead>

                                            <tbody>
                                                {billingHistory.map((b, index) => (
                                                    <tr key={index}>
                                                        <td>
                                                            {new Date(b.date).toLocaleDateString()}
                                                        </td>
                                                        <td>{b.service}</td>
                                                        <td>₹ {b.amount}</td>
                                                        <td>{b.paymentStatus}</td>
                                                    </tr>
                                                ))}
                                            </tbody>
                                        </table>
                                    ) : (
                                        <p className="text-muted text-center">
                                            No billing records found for this patient.
                                        </p>
                                    )}
                                </div>

                                {/* Modal Footer */}
                                <div className="modal-footer">
                                    <button className="btn btn-secondary" onClick={closePopup}>
                                        Close
                                    </button>
                                </div>

                            </div>
                        </div>
                    </div>
                )}

            </div>
        </Layout>
    );
};

export default Patients;
